lse,false,false,false local function GetRole(plr)if not plr then return "Innocent" end local bp=plr:FindFirstChild("Backpack")local ch=plr.Character if(bp and bp:FindFirstChild("Knife"))or(ch and ch:FindFirstChild("Knife"))then return "Murderer" elseif(bp and bp:FindFirstChild("Gun"))or(ch and ch:FindFirstChild("Gun"))then return "Sheriff" end return "Innocent" end AddToggle(pCombat,"ระบบนายอำเภอควักปืนวาร์ปยิงอัตโนมัติ (ดาเมจจริง)",function(v)SheriffAutoKill=v task.spawn(function()while SheriffAutoKill do task.wait(0.05)pcall(function()local lp=game:GetService("Players").LocalPlayer if GetRole(lp)=="Sheriff" and lp.Character and lp.Character:FindFirstChild("HumanoidRootPart") then local gun=lp.Character:FindFirstChild("Gun") or lp.Backpack:FindFirstChild("Gun") if gun then if gun.Parent==lp.Backpack then lp.Character.Humanoid:EquipTool(gun)end for _,p in ipairs(game:GetService("Players"):GetPlayers()) do if p~=lp and GetRole(p)=="Murderer" and p.Character and p.Character:FindFirstChild("HumanoidRootPart") and p.Character.Humanoid.Health>0 then lp.Character.HumanoidRootPart.CFrame=p.Character.HumanoidRootPart.CFrameCFrame.new(0,1,5)workspace.CurrentCamera.CFrame=CFrame.new(workspace.CurrentCamera.CFrame.Position,p.Character.HumanoidRootPart.Position)gun:Activate()pcall(function()firetouchinterest(p.Character.HumanoidRootPart,gun.Handle,0)firetouchinterest(p.Character.HumanoidRootPart,gun.Handle,1)end)task.wait(0.1)end end end end end)end end)end)AddToggle(pCombat,"ระบบดึงฆาตกรมายิงรับดาเมจจริง",function(v)PullMurd=v task.spawn(function()while PullMurd do task.wait(0.1)pcall(function()local lp=game:GetService("Players").LocalPlayer if(GetRole(lp)=="Sheriff" or GetRole(lp)=="Innocent")and lp.Character and lp.Character:FindFirstChild("HumanoidRootPart") then local gun=lp.Character:FindFirstChild("Gun") or lp.Backpack:FindFirstChild("Gun") if gun then if gun.Parent==lp.Backpack then lp.Character.Humanoid:EquipTool(gun)end for _,p in ipairs(game:GetService("Players"):GetPlayers()) do if p~=lp and GetRole(p)=="Murderer" and p.Character and p.Character:FindFirstChild("HumanoidRootPart") and p.Character.Humanoid.Health>0 then p.Character.HumanoidRootPart.CFrame=lp.Character.HumanoidRootPart.CFrameCFrame.new(0,0,-6)workspace.CurrentCamera.CFrame=CFrame.new(workspace.CurrentCamera.CFrame.Position,p.Character.HumanoidRootPart.Position)gun:Activate()pcall(function()firetouchinterest(p.Character.HumanoidRootPart,gun.Handle,0)firetouchinterest(p.Character.HumanoidRootPart,gun.Handle,1)end)task.wait(0.1)end end end end end)end end)end)AddToggle(pCombat,"ระบบดึงทุกคนมาฟันรับดาเมจจริง",function(v)PullInno=v task.spawn(function()while PullInno do task.wait(0.1)pcall(function()local lp=game:GetService("Players").LocalPlayer if GetRole(lp)=="Murderer" and lp.Character and lp.Character:FindFirstChild("HumanoidRootPart") then local kn=lp.Character:FindFirstChild("Knife") or lp.Backpack:FindFirstChild("Knife") if kn then if kn.Parent==lp.Backpack then lp.Character.Humanoid:EquipTool(kn)end for _,p in ipairs(game:GetService("Players"):GetPlayers()) do if p~=lp and p.Character and p.Character:FindFirstChild("HumanoidRootPart") and p.Character.Humanoid.Health>0 then p.Character.HumanoidRootPart.CFrame=lp.Character.HumanoidRootPart.CFrame*CFrame.new(0,0,-2)kn:Activate()pcall(function()firetouchinterest(p.Character.HumanoidRootPart,kn.Handle,0)firetouchinterest(p.Character.HumanoidRootPart,kn.Handle,1)end)task.wait(0.05)end end end end end)end end)end)AddToggle(pCombat,"ระบบมีดบินไล่ล่าหัวอัตโนมัติ (Fly Knife)",function(v)FlyKnife=v task.spawn(function()while FlyKnife do task.wait(0.1)pcall(function()local lp=game:GetService("Players").LocalPlayer if GetRole(lp)=="Murderer" and lp.Character and lp.Character:FindFirstChild("Knife") then local kn=lp.Character.Knife for _,p in ipairs(game:GetService("Players"):GetPlayers()) do if p~=lp and p.Character and p.Character:FindFirstChild("Head") and p.Character.Humanoid.Health>0 then kn.Handle.CFrame=p.Character.