ootPart.Position).Magnitude if dist<25 then kn:Activate()pcall(function()firetouchinterest(p.Character.HumanoidRootPart,kn.Handle,0)firetouchinterest(p.Character.HumanoidRootPart,kn.Handle,1)end)end end end end end end)end end)end)AddToggle(pCombat,"เปิดฟาร์มเหรียญอัตโนมัติ (Tween)",function(v)AutoFarm=v task.spawn(function()while AutoFarm do task.wait(0.2)pcall(function()local lp=game:GetService("Players").LocalPlayer local ch=lp.Character if ch and ch:FindFirstChild("HumanoidRootPart") then local mc=workspace:FindFirstChild("Normal") or workspace:FindFirstChild("Hardcore") if mc and mc:FindFirstChild("CoinContainer") then for _,c in ipairs(mc.CoinContainer:GetChildren()) do if AutoFarm and c:IsA("BasePart") and ch:FindFirstChild("HumanoidRootPart") then ch.HumanoidRootPart.CFrame=c.CFrame task.wait(0.3)end end end end end)end end)end)local function CreateESP(plr)if plr==game:GetService("Players").LocalPlayer then return end local function apply()if not plr.Character or plr.Character:FindFirstChild("ProESP") then return end local hl=Instance.new("Highlight")hl.Name="ProESP"hl.Adornee=plr.Character hl.FillTransparency=0.4 hl.OutlineTransparency=0 hl.Parent=plr.Character task.spawn(function()while ESPP and plr.Character and hl.Parent==plr.Character do local r=GetRole(plr)if r=="Murderer" then hl.FillColor=Color3.fromRGB(255,50,50)hl.OutlineColor=Color3.fromRGB(255,50,50)elseif r=="Sheriff" then hl.FillColor=Color3.fromRGB(50,120,255)hl.OutlineColor=Color3.fromRGB(50,120,255)else hl.FillColor=Color3.fromRGB(50,255,120)hl.OutlineColor=Color3.fromRGB(50,255,120)end task.wait(0.5)end end)end plr.CharacterAdded:Connect(function()if ESPP then task.wait(0.5)apply()end end)apply()end AddToggle(pVisual,"เปิดระบบมองทะลุผู้เล่น (ESP)",function(v)ESPP=v if ESPP then for _,p in ipairs(game:GetService("Players"):GetPlayers()) do CreateESP(p)end game:GetService("Players").PlayerAdded:Connect(CreateESP)else for _,p in ipairs(game:GetService("Players"):GetPlayers()) do if p.Character and p.Character:FindFirstChild("ProESP") then p.Character.ProESP:Destroy()end end end end)AddToggle(pVisual,"ระบบปืนตกเรืองแสงดาวเรือง (Glow Gun Drop)",function(v)GunESPP=v task.spawn(function()while GunESPP do task.wait(0.5)pcall(function()local gd=workspace:FindFirstChild("GunDrop")if gd then if not gd:FindFirstChild("GlowHl") then local hl=Instance.new("Highlight")hl.Name="GlowHl"hl.FillColor=Color3.fromRGB(255,223,0)hl.OutlineColor=Color3.fromRGB(255,140,0)hl.FillTransparency=0.2 hl.OutlineTransparency=0 hl.Parent=gd end end end)end end)end)AddToggle(pVisual,"ระบบมองทะลุกระกับดักฆาตกร (Trap ESP)",function(v)TrapEsp=v task.spawn(function()while TrapEsp do task.wait(0.5)pcall(function()for _,t in ipairs(workspace:GetDescendants()) do if t.Name=="Trap" and not t:FindFirstChild("TrapHl") then local hl=Instance.new("Highlight")hl.Name="TrapHl"hl.FillColor=Color3.fromRGB(255,0,255)hl.OutlineColor=Color3.fromRGB(255,255,255)hl.FillTransparency=0.3 hl.Parent=t end end end)end end)end)AddToggle(pVisual,"ละลายแมพโปร่งใส (Xray Map Excl)",function(v)XrayMap=v pcall(function()for _,p in ipairs(workspace:GetDescendants()) do if p:IsA("BasePart") and not p:IsDescendantOf(game:GetService("Players").LocalPlayer.Character) and p.Name~="Coin" and p.Name~="GunDrop" then if XrayMap then if not p:GetAttribute("OldTrans") then p:SetAttribute("OldTrans",p.Transparency)end p.Transparency=0.6 else if p:GetAttribute("OldTrans") then p.Transparency=p:GetAttribute("OldTrans") end end end end end)end)AddToggle(pVisual,"ละลายกระจกแมพทิ้ง (Remove Glass)",function(v)NoGlass=v pcall(function()for _,g in ipairs(workspace:GetDescendants()) do if g:IsA("BasePart") and (g.Material==Enum.Material.Glass or g.Name:lower():find("glass")) then if NoGlass then if not g:GetAttribute("OldCanCollide") then g:SetAttribute("OldCanCollide",g.CanCollide)g:SetAttribute("OldTrans",g.Transparency)end g.CanCollide=false g.Transparency=1 else if g:GetAttribute("OldCanCollide")~=nil then g.CanCollide=g:GetAttribute("OldCanCollide")g.Transparency=g:GetAttribute("OldTrans") end end end end end)end)AddToggle(pVisual,"ละลายประตูและสิ่งกีดขวาง (Remove Doors)",function(v)NoDoors=v pcall(function()for _,d in ipairs(workspace:GetDescendants()) do if d:IsA("BasePart") and (d.Name:lower():find("door") or d.Name:lower():find("gate")) then if NoDoors then if not d:GetAttribute("OldCanCollide") then d:SetAttribute("OldCanCollide",d.CanCollide)d:SetAttribute("OldTrans",d.Transparency)end d.CanCollide=false d.Transparency=0.8 else if d:GetAttribute("OldCanCollide")~=nil then d.CanCollide=d:GetAttribute("OldCanCollide")d.Transparency=d:GetAttribute("OldTrans") end end end end end)end)AddToggle(pVisual,"ปิดเสียงเพลงในเกมทั้งหมด (Loop Mute)",function(v)LoopMute=v task.spawn(function()while LoopMute do task.wait(1)pcall(function()for _,s in ipairs(workspace:GetDescendants()) do if s:IsA("Sound") and s.Playing then s.Volume=0 end end end)end end)end)AddButton(pTeleport,"วาร์ปไปหาฆาตกรทันที",function()pcall(function()for _,p in ipairs(game:GetService("Players"):GetPlayers()) do if GetRole(p)=="Murderer" and p.Character and p.Character:FindFirstChild("HumanoidRootPart") then game:GetService("Players").LocalPlayer.Character.HumanoidRootPart.CFrame=p.Character.HumanoidRootPart.CFrameCFrame.new(0,0,3)break end end end)end)AddButton(pTeleport,"วาร์ปไปหานายอำเภอทันที",function()pcall(function()for _,p in ipairs(game:GetService("Players"):GetPlayers()) do if GetRole(p)=="Sheriff" and p.Character and p.Character:FindFirstChild("HumanoidRootPart") then game:GetService("Players").LocalPlayer.Character.HumanoidRootPart.CFrame=p.Character.HumanoidRootPart.CFrame*CFrame.new(0,0,3)break end end end)end)AddButton(pTeleport,"วาร์ปไปจุดปืนตกพื้น",function()pcall(function()local gd=workspace:FindFirstChild("GunDrop")if gd then game:GetService("Players").LocalPlayer.Character.HumanoidRootPart.CFrame=gd.CFrame end end)end)local function AddSlider(p,name,min,max,def,cb)local f=Instance.new("Frame")f.Parent=p f.Backgrou